script:
async function openEditProfileModal() {
  const userName = page_data.user.user;
  if (!userName || userName === "Guest") {
    window.toast.error("You must be logged in to edit your profile");
    return;
  }

  try {
    const userData = page_data.user;

    const dialogHtml = `
            <div class="edit-profile-form" style="display: flex; flex-direction: column; gap: 1rem;">
                <div class="form-group">
                    <label style="display: block; font-size: 13px; margin-bottom: 0.25rem; color: var(--ink-gray-7);">First Name</label>
                    <input type="text" id="edit-first-name" style="font-size: 14px; width: 100%; padding: 8px 6px; line-height: 1.15; border: 1px solid var(--f-dialog-border); border-radius: 8px; background-color: var(--f-dialog-bg); color: var(--f-dialog-text-body);" value="${userData.first_name || ""}">
                </div>
                <div class="form-group">
                    <label style="display: block; font-size: 13px; margin-bottom: 0.25rem; color: var(--ink-gray-7);">Last Name</label>
                    <input type="text" id="edit-last-name" style="font-size: 14px; width: 100%; padding: 8px 6px; line-height: 1.15; border: 1px solid var(--f-dialog-border); border-radius: 8px; background-color: var(--f-dialog-bg); color: var(--f-dialog-text-body);" value="${userData.last_name || ""}">
                </div>
                <div class="form-group">
                    <label style="display: block; font-size: 13px; margin-bottom: 0.25rem; color: var(--ink-gray-7);">Handle</label>
                    <input type="text" id="edit-handle" style="font-size: 14px; width: 100%; padding: 8px 6px; line-height: 1.15; border: 1px solid var(--f-dialog-border); border-radius: 8px; background-color: var(--f-dialog-bg); color: var(--f-dialog-text-body);" value="${userData.handle.split("@")[1] || ""}">
                </div>
                <div class="form-group">
                    <label style="display: block; font-size: 13px; margin-bottom: 0.25rem; color: var(--ink-gray-7);">Company</label>
                    <input type="text" id="edit-company" style="font-size: 14px; width: 100%; padding: 8px 6px; line-height: 1.15; border: 1px solid var(--f-dialog-border); border-radius: 8px; background-color: var(--f-dialog-bg); color: var(--f-dialog-text-body);" value="${userData.company || ""}">
                </div>
                <div class="form-group">
                    <label style="display: block; font-size: 13px; margin-bottom: 0.25rem; color: var(--ink-gray-7);">Designation</label>
                    <input type="text" id="edit-designation" style="font-size: 14px; width: 100%; padding: 8px 6px; line-height: 1.15; border: 1px solid var(--f-dialog-border); border-radius: 8px; background-color: var(--f-dialog-bg); color: var(--f-dialog-text-body);" value="${userData.designation || ""}">
                </div>
                <div class="form-group">
                    <label style="display: block; font-size: 13px; margin-bottom: 0.25rem; color: var(--ink-gray-7);">Bio</label>
                    <textarea id="edit-bio" rows="3" style="font-size: 14px; width: 100%; padding: 8px 6px; line-height: 1.15; border: 1px solid var(--f-dialog-border); border-radius: 8px; resize: vertical; background-color: var(--f-dialog-bg); color: var(--f-dialog-text-body);">${userData.bio || ""}</textarea>
                </div>
            </div>
        `;

    window.dialog({
      title: "Edit Profile",
      size: "md",
      html: dialogHtml,
      actions: [
        {
          label: "Save Changes",
          variant: "solid",
          onClick: async (close) => {
            const newFirstName =
              document.getElementById("edit-first-name").value;
            const newLastName = document.getElementById("edit-last-name").value;
            const newHandle = document.getElementById("edit-handle").value;
            const newCompany = document.getElementById("edit-company").value;
            const newDesignation =
              document.getElementById("edit-designation").value;
            const newBio = document.getElementById("edit-bio").value;

            const updates = [];

            // Update User name if changed
            if (
              newFirstName !== userData.first_name ||
              newLastName !== userData.last_name
            ) {
              await frappeClient.setValue("User", userName, {
                first_name: newFirstName,
                last_name: newLastName,
              });
            }

            // Update Cafe User fields
            const userDataUpdates = {};
            const currentHandle = userData.handle
              ? userData.handle.includes("@")
                ? userData.handle.split("@")[1]
                : userData.handle
              : "";

            if (newHandle !== currentHandle) {
              userDataUpdates.handle = newHandle;
            }
            if (newCompany !== userData.company)
              userDataUpdates.company = newCompany;
            if (newDesignation !== userData.designation)
              userDataUpdates.designation = newDesignation;
            if (newBio !== userData.bio) userDataUpdates.bio = newBio;

            try {
              await frappeClient.setValue(
                "Cafe User",
                userName,
                userDataUpdates,
              );
              window.toast.success("Profile updated successfully");
              close();

              if (userDataUpdates.handle) {
                const url = new URL(window.location.href);
                url.pathname = url.pathname.replace(currentHandle, newHandle);
                setTimeout(() => (window.location.href = url.href), 500);
              } else {
                setTimeout(() => window.location.reload(), 500);
              }
            } catch (error) {
              console.log(error);
              window.toast.error(error.message || "Failed to update profile");
            }
            // if (Object.keys(userDataUpdates).length > 0) {
            //   for (const [field, value] of Object.entries(userDataUpdates)) {
            //     updates.push(
            //     );
            //   }
            // }

            // if (updates.length > 0) {
            //   try {
            //     await Promise.all(updates);
            //     window.toast.success("Profile updated successfully");
            //     close();
            //     setTimeout(() => window.location.reload(), 500);
            //   } catch (err) {
            //     console.error("Update failed:", err);
            //     window.toast.error("Failed to update profile");
            //   }
            // } else {
            //   close();
            // }
          },
        },
        {
          label: "Cancel",
          onClick: (close) => close(),
        },
      ],
    });
  } catch (err) {
    console.error("Failed to fetch profile data:", err);
    window.toast.error("Could not load profile data");
  }
}

function init() {
  const editButton = document.getElementById("edit-profile-button");
  console.log("🚀 ~ init ~ editButton:", editButton);
  if (editButton) {
    editButton.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      openEditProfileModal();
    });
  }
}

init();
